# generated by actlith gen from .actlith; do not edit
# shellcheck shell=bash
#
# verify-cache.sh CACHE PACKAGE SYSTEM...
#
# Every SYSTEM's `.#packages.<system>.<PACKAGE>` output path answers 200
# from https://<CACHE>.cachix.org (kind `build`, src/build:V30). A failed
# cachix push does not fail its job (src/build:R4), so this is the check
# that catches an empty cache. Evaluation is cross-system: one runner
# resolves every path without building any of them.
set -euo pipefail

if [ "$#" -lt 3 ]; then
  echo "usage: verify-cache.sh CACHE PACKAGE SYSTEM..." >&2
  exit 2
fi
cache="$1"
package="$2"
shift 2

rc=0
for sys in "$@"; do
  path="$(nix eval --raw ".#packages.$sys.$package")"
  name="${path##*/}"
  hash="${name%%-*}"
  url="https://$cache.cachix.org/$hash.narinfo"
  code="$(curl -s -o /dev/null -w '%{http_code}' "$url" || true)"
  echo "verify-cache: $sys $hash -> $code"
  if [ "$code" != 200 ]; then
    rc=1
  fi
done

if [ "$rc" -ne 0 ]; then
  echo "::error::$package missing from $cache.cachix.org after a main build." >&2
  echo "::error::Check CACHIX_AUTH_TOKEN: a per-cache token with write access" >&2
  echo "::error::to $cache. A failed cachix push does not fail its job." >&2
  exit 1
fi
